const input = readFileSync(0, "utf8");

function searchRotated(nums: number[], target: number): number {
  let lo = 0;
  let hi = nums.length - 1;
  while (lo <= hi) {
    const mid = Math.floor((lo + hi) / 2);
    const first = nums[lo] ?? 0;
    const middle = nums[mid] ?? 0;
    const last = nums[hi] ?? 0;
    if (middle === target) {
      return mid;
    }
    if (first <= middle) {
      // The left half, lo to mid, is sorted.
      if (first <= target && target < middle) {
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    } else {
      // The right half, mid to hi, is sorted.
      if (middle < target && target <= last) {
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
  }
  return -1;
}

